function showIntro(){
  if($('#intro-modal'))return;
  const previous=document.activeElement, steps=['introStepOne','introStepTwo','introStepThree'];let step=0;
  app.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="intro-modal"><section class="modal intro-modal" role="dialog" aria-modal="true" aria-labelledby="intro-title"><div class="eyebrow">TAKEVERA · ${tr('gettingStarted')}</div><h2 id="intro-title">${tr('introTitle')}</h2><p>${tr('introBody')}</p><p id="intro-progress" class="subtitle" aria-live="polite"></p><p id="intro-step" aria-live="polite"></p><div class="tip">${tr('introOffline')}</div><div class="modal-actions"><button class="btn" id="intro-skip">${tr('skipIntro')}</button><button class="btn" id="intro-back">${tr('introPrevious')}</button><button class="btn primary" id="intro-next"></button></div></section></div>`);
  const close=()=>{localStorage.setItem('scriptstudio-intro-seen','1');$('#intro-modal')?.remove();previous?.focus?.()};
  const update=()=>{$('#intro-progress').textContent=tr('introProgress').replace('{current}',String(step+1)).replace('{total}',String(steps.length));$('#intro-step').textContent=tr(steps[step]);$('#intro-back').disabled=step===0;$('#intro-next').textContent=step===steps.length-1?(project?tr('introFinish'):tr('introCreateProject')):tr('introNext')};
  $('#intro-skip').onclick=close;$('#intro-back').onclick=()=>{step--;update()};$('#intro-next').onclick=()=>{if(step<steps.length-1){step++;update()}else{close();if(!project)addProject()}};$('#intro-modal').addEventListener('keydown',event=>{if(event.key==='Escape')close()});update();$('#intro-next').focus();
}
