  const presets={claude:{endpoint:'https://api.anthropic.com/v1',model:'claude-sonnet-4-6'},gemini:{endpoint:'https://generativelanguage.googleapis.com/v1beta/openai',model:'gemini-3.8-flash'},grok:{endpoint:'https://api.x.ai/v1',model:'grok-4.7'}};
  let previousProvider=provider.value;const endpoints={},models={[provider.value]:model.value};if(!presets[provider.value])endpoints[provider.value]=endpoint.value;
  const update=()=>{const preset=presets[provider.value];endpoint.readOnly=!!preset;if(preset)endpoint.value=preset.endpoint;workspace.hidden=provider.value!=='claude';};
