function projectSearchResults(query=projectSearchQuery){const q=String(query||'').trim().toLocaleLowerCase(lang==='nl'?'nl-NL':'en-US');if(!project||q.length<2)return [];const out=[],skip=/^(?:id|src|image|thumbnail|phone|token|password|apiKey|updatedAt|createdAt|commentTargetId|_ssId)$/i;const route=path=>{const x=path.toLowerCase();if(/moodboard|storyboard/.test(x))return 'boards';if(/inventory/.test(x))return 'production';if(/scenes|script/.test(x))return 'script';if(/characters|locations|timeline|worldrules|objects|continuity|styleguide|projectnotes/.test(x))return 'bible';if(/shootdays|people|crew|cast|shots|shortlists|tasks|budget|light|sound|breakdown|equipment|props|costumes|transport/.test(x))return 'production';return 'bible'};const walk=(value,path='project',scene=null)=>{if(value==null||out.length>=100)return;if(Array.isArray(value)){value.forEach((item,index)=>walk(item,`${path}[${index}]`,path==='project.scenes'?index:scene));return}if(typeof value==='object'){for(const [key,item] of Object.entries(value)){if(skip.test(key)||key==='assets')continue;walk(item,`${path}.${key}`,scene)}return}if(typeof value!=='string'&&typeof value!=='number'&&typeof value!=='boolean')return;const text=String(value);if(!text.toLocaleLowerCase(lang==='nl'?'nl-NL':'en-US').includes(q))return;const clean=text.replace(/\s+/g,' ').trim();out.push({path,label:path.replace(/^project\./,'').replace(/\[(\d+)\]/g,' #$1').replace(/[._]/g,' · '),snippet:clean.length>180?`${clean.slice(0,177)}…`:clean,section:route(path),sceneIndex:scene})};walk(project);return out}
function projectSearchDialog(){if(!project||!projectSearchOpen)return '';const results=projectSearchResults();return `<div class="project-search-backdrop" id="project-search-backdrop"><section class="project-search-dialog" role="dialog" aria-modal="true" aria-labelledby="project-search-title"><header><h2 id="project-search-title">${tr('projectSearchTitle')} · ${esc(project.title)}</h2><button type="button" class="btn quiet" id="close-project-search" aria-label="${tr('close')}">×</button></header><input id="project-search-input" type="search" value="${esc(projectSearchQuery)}" placeholder="${tr('projectSearchPlaceholder')}" autofocus><div class="project-search-results" role="listbox">${results.length?results.map((item,index)=>`<button type="button" class="project-search-result" data-project-result="${index}"><small>${tr(item.section)} · ${esc(item.label)}</small><span>${esc(item.snippet)}</span></button>`).join(''):`<p class="project-search-empty">${projectSearchQuery.trim().length<2?tr('projectSearchHint'):tr('projectSearchNoResults')}</p>`}</div><footer>${tr('projectSearchShortcut')}</footer></section></div>`}
