function normalizedTaskStatus(value){const status=String(value||'').trim().toLocaleLowerCase();if(['done','gereed'].includes(status))return'done';if(['confirmed','bevestigd'].includes(status))return'confirmed';return'todo'}
function taskStatusLabel(value){return tr(({todo:'taskTodo',confirmed:'taskConfirmed',done:'taskDone'})[normalizedTaskStatus(value)])}
