async function importDOCX(){try{const file=await window.studio.importDOCX();if(!file)return;const scenes=parseDOCX(file.xml),envelope=file.embeddedProject?JSON.parse(file.embeddedProject):null,restored=restoreEmbeddedProject(envelope,scenes);if(file.embeddedProject&&!restored)throw new Error(tr('embeddedProjectInvalid'));const choice=await previewScriptImport('DOCX',file.name,scenes,{embedded:!!restored,warningKey:'docxImportConfirm'});if(!choice)return;if(choice==='project'&&restored){await activateImportedProject(restored);toast(tr('docxEmbeddedImported'));return}if(!replaceImportedScenes(scenes,file.name,'docxImportConfirm',true))return;await persist();render();toast(tr('docxImported'))}catch(error){toast(`${tr('docxImportFailed')}: ${error.message}`)}}
async function exportDOCX(){try{if(!confirm(tr('docxExportConfirm')))return;const includeProject=confirm(tr('docxExportProjectDataConfirm')),envelope=includeProject?JSON.stringify({format:'scriptstudio-docx-project',version:1,project}):undefined;const result=await window.studio.exportDOCX(project.title,buildDOCX(project),envelope);if(!result?.canceled)await askChoice(tr('exportCheckTitle'),tr(includeProject?'docxExportedWithData':'docxExportedScriptOnly')+'\n\n'+tr('exportVerified'),[{label:tr('introFinish'),value:'done'}])}catch(error){toast(`${tr('docxExportFailed')}: ${error.message}`)}}
function parsePDFScript(rawText){const lines=String(rawText||'').replace(/\f/g,'\n').replace(/\r\n?/g,'\n').split('\n').map(line=>line.trim()).filter(Boolean);if(!lines.length)throw new Error(tr('pdfNoText'));const scenes=[];let current=null;for(const line of lines){if(fountainHeading(line)){current={heading:line,action:'',character:'',dialogue:'',location:'',duration:0,notes:'',elements:[]};scenes.push(current)}else{if(!current){current={heading:'',action:'',character:'',dialogue:'',location:'',duration:0,notes:'',elements:[]};scenes.push(current)}current.action+=(current.action?'\n':'')+line}}return scenes}
async function importPDF(){try{const file=await window.studio.importPDF();if(!file)return;const scenes=parsePDFScript(file.text),preview=[tr('importPreviewCharacters').replace('{n}',String(String(file.text||'').length)),tr('importPreviewReview'),tr('pdfPreviewMeta').replace('{pages}',String(file.pageCount)).replace('{scenes}',String(scenes.length)),...(file.ocrPages?[tr('pdfOCRPages').replace('{n}',String(file.ocrPages))]:[]),...scenes.slice(0,8).map((scene,index)=>`${index+1}. ${scene.heading||tr('pdfUnstructured')}\n${(scene.action||'').slice(0,150)}`),...(scenes.length>8?[tr('pdfMoreScenes').replace('{n}',String(scenes.length-8))]:[])].join('\n\n');const choice=await askChoice(tr('pdfPreviewTitle'),`${tr('pdfImportWarning')}\n\n${preview}`,[{label:tr('pdfImportButton'),value:'import'}]);if(choice!=='import')return;if(!replaceImportedScenes(scenes,file.name,'pdfImportWarning',true))return;await persist();render();toast(tr('pdfImported'))}catch(error){toast(`${tr('pdfImportFailed')}: ${error.message}`)}}
const searchableSceneFields=['heading','action','character','dialogue','location','act'];
function countScriptMatches(query){if(!query)return 0;const escaped=query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),pattern=new RegExp(escaped,'gi');return (project.scenes||[]).reduce((sum,scene)=>sum+searchableSceneFields.reduce((n,key)=>n+((String(scene[key]||'').match(pattern)||[]).length),0)+(scene.elements||[]).reduce((n,item)=>n+((String(item.text||'').match(pattern)||[]).length),0),0)}
function replaceScriptText(query,replacement,all){if(!query)return 0;const escaped=query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),scenes=all?(project.scenes||[]):[project.scenes?.[sceneIndex]].filter(Boolean);let count=0;for(const scene of scenes){if(scene.locked)continue;for(const key of searchableSceneFields){const text=String(scene[key]||'');if(!text)continue;const matches=text.match(new RegExp(escaped,all?'gi':'i'));if(!matches)continue;if(!all){scene[key]=text.replace(new RegExp(escaped,'i'),replacement);return 1}count+=matches.length;scene[key]=text.replace(new RegExp(escaped,'gi'),replacement)}for(const item of scene.elements||[]){const text=String(item.text||''),matches=text.match(new RegExp(escaped,all?'gi':'i'));if(!matches)continue;if(!all){item.text=text.replace(new RegExp(escaped,'i'),replacement);return 1}count+=matches.length;item.text=text.replace(new RegExp(escaped,'gi'),replacement)}}return count}

