function scriptReadingView(visibleScenes,words,minutes){const cards=scriptViewMode==='cards';return `<div class="script-reading-view">${scriptViewModeControls()}<header><h1>${esc(project.title)}</h1><p>${visibleScenes.length} ${tr('scenes')} · ${words} ${tr('words')} · ${minutes} ${tr('minutes')}</p></header>${cards?`<div class="script-card-grid">${visibleScenes.map(({x,i})=>`<article class="script-scene-card"><div class="eyebrow">${x.locked?'🔒 ':''}${tr('scene')} ${String(i+1).padStart(2,'0')} · ${esc(x.location||'—')}</div><h2>${esc(x.heading||`${tr('scene')} ${i+1}`)}</h2>${x.images?.[0]?.src?`<img src="${esc(x.images[0].src)}" alt="${esc(x.images[0].caption||tr('referenceImage'))}">`:''}<p>${esc(String(x.action||'').slice(0,520))}${String(x.action||'').length>520?'…':''}</p>${x.character||x.dialogue?`<blockquote><b>${esc(x.character||'')}</b><br>${esc(String(x.dialogue||'').slice(0,300))}</blockquote>`:''}<button type="button" class="btn" data-open-scene="${i}">${tr('editScene')}</button></article>`).join('')||`<div class="empty">${tr('noSceneMatches')}</div>`}</div>`:`<article class="continuous-script">${visibleScenes.map(({x,i})=>`<section class="continuous-scene"><button type="button" class="continuous-scene-heading" data-open-scene="${i}">${String(i+1).padStart(2,'0')} · ${esc(x.heading||`${tr('scene')} ${i+1}`)} · ${tr('editScene')}</button>${x.action?`<p>${esc(x.action)}</p>`:''}${x.character||x.dialogue?`<div class="continuous-dialogue"><b>${esc(x.character||'')}</b><p>${esc(x.dialogue||'')}</p></div>`:''}${(x.elements||[]).map(item=>`<p class="continuous-element"><small>${sceneElementLabel(item.type||'custom')}</small><br>${esc(item.text||'')}</p>`).join('')}${x.notes?`<p class="continuous-notes"><small>${tr('notes')}</small><br>${esc(x.notes)}</p>`:''}</section>`).join('')||`<div class="empty">${tr('noSceneMatches')}</div>`}</article>`}</div>`}
