function timelineEventsMarkup(){project.timelineEvents||=[];const rows=project.timelineEvents.map((event,index)=>`<article class="timeline-event-row"><input type="datetime-local" data-timeline-event="${index}" data-key="when" value="${esc(event.when||'')}" aria-label="${tr('timelineEventTime')}"><input data-timeline-event="${index}" data-key="title" value="${esc(event.title||'')}" placeholder="${tr('timelineEvent')}" aria-label="${tr('timelineEvent')}"><select data-timeline-event="${index}" data-key="scene" aria-label="${tr('timelineEventScene')}"><option value="">${tr('timelineEventNoScene')}</option>${(project.scenes||[]).map((scene,sceneIndex)=>`<option value="${sceneIndex}" ${String(event.scene)===String(sceneIndex)?'selected':''}>${String(sceneIndex+1).padStart(2,'0')} · ${esc(scene.heading||tr('scene'))}</option>`).join('')}</select><textarea data-timeline-event="${index}" data-key="notes" placeholder="${tr('notes')}">${esc(event.notes||'')}</textarea><div class="timeline-event-actions"><button type="button" class="btn quiet" data-timeline-event-move="up" data-index="${index}" ${index===0?'disabled':''} aria-label="${tr('moveUp')}">↑</button><button type="button" class="btn quiet" data-timeline-event-move="down" data-index="${index}" ${index===project.timelineEvents.length-1?'disabled':''} aria-label="${tr('moveDown')}">↓</button><button type="button" class="btn quiet" data-timeline-event-remove="${index}" aria-label="${tr('delete')}">⌫</button></div></article>`).join('');return `<section class="production-card timeline-events"><div class="section-head"><div><h3>${tr('timelineEvents')}</h3><p class="subtitle">${tr('timelineEventsHint')}</p></div><button type="button" class="btn" id="add-timeline-event">＋ ${tr('addTimelineEvent')}</button></div>${rows||`<p class="subtitle">${tr('timelineEventsEmpty')}</p>`}</section>`}
function bindBibleTimelineEvents(){document.querySelectorAll('[data-timeline-event]').forEach(input=>input.addEventListener(input.tagName==='SELECT'?'change':'input',()=>{const event=project?.timelineEvents?.[Number(input.dataset.timelineEvent)];if(!event)return;const key=input.dataset.key;event[key]=key==='scene'?(input.value===''?'':Number(input.value)):input.value;scheduleSave()}));$('#add-timeline-event')?.addEventListener('click',()=>{project.timelineEvents||=[];project.timelineEvents.push({when:'',title:'',scene:'',notes:''});render();scheduleSave()});document.querySelectorAll('[data-timeline-event-move]').forEach(button=>button.addEventListener('click',()=>{const events=project?.timelineEvents,index=Number(button.dataset.index),next=index+(button.dataset.timelineEventMove==='up'?-1:1);if(!events||next<0||next>=events.length)return;[events[index],events[next]]=[events[next],events[index]];render();scheduleSave()}));document.querySelectorAll('[data-timeline-event-remove]').forEach(button=>button.addEventListener('click',()=>{project.timelineEvents?.splice(Number(button.dataset.timelineEventRemove),1);render();scheduleSave()}))}
