const productionTemplateSections=['bible','productionDetails','schedule','castCrew','safety','scenes','shotlist','shortlists','light','sound','equipment','tasks','budget','referenceImages','storyboard','moodboard'];
const dailyTemplateSections=new Set(['productionDetails','schedule','castCrew','safety','scenes','shotlist']);
function ensureProductionTemplates(){project.productionTemplates||=[];project.customBookSections||=[];let changed=false;if(!project.productionTemplates.length){project.productionTemplates.push({id:'standard',name:tr('standardExportTemplate'),sections:[...productionTemplateSections]});changed=true}for(const template of project.productionTemplates){if(!template.id){template.id=id();changed=true}if(!Array.isArray(template.sections)){template.sections=[...productionTemplateSections];changed=true}if(template.id==='standard')for(const key of ['equipment','referenceImages'])if(!template.sections.includes(key)){template.sections.push(key);changed=true}const allowed=new Set([...productionTemplateSections,...project.customBookSections.map(item=>`custom:${item.id}`)]),unique=[...new Set(template.sections.filter(key=>allowed.has(key)))];const normalized=[...unique.filter(key=>dailyTemplateSections.has(key)),...unique.filter(key=>!dailyTemplateSections.has(key))];if(JSON.stringify(normalized)!==JSON.stringify(template.sections)){template.sections=normalized;changed=true}}if(!project.productionTemplates.some(template=>template.id===activeProductionTemplateId))activeProductionTemplateId=project.productionTemplates[0].id;if(changed)scheduleSave();return project.productionTemplates}
function activeProductionTemplate(){const templates=ensureProductionTemplates();return templates.find(template=>template.id===activeProductionTemplateId)||templates[0]}
function productionTemplateSectionLabel(key){if(String(key).startsWith('custom:'))return project.customBookSections?.find(item=>`custom:${item.id}`===key)?.title||tr('customBookSectionName');return tr(({shortlists:'shortlist',safety:'safetyLogistics',equipment:'equipmentList',referenceImages:'referenceImages'})[key]||key)}
