function equipmentListPrintMarkup(){const rows=(project.equipment||[]).map(item=>{const scenes=(item.scenes||[]).map(index=>project.scenes[Number(index)]?.heading).filter(Boolean),shots=(item.shots||[]).map(index=>project.shots[Number(index)]?.description||`${tr('shot')} ${Number(index)+1}`).filter(Boolean);return `<article class="production-report-item"><h3>${esc(item.name||tr('itemName'))}</h3><p>${esc(item.category||tr('equipment'))} · ${tr('equipmentQuantity')}: ${esc(item.quantity??1)} · ${tr(item.status||'needed')} · ${tr('owner')}: ${esc(item.owner||'—')}</p>${scenes.length?`<p><b>${tr('scenes')}:</b> ${scenes.map(esc).join(', ')}</p>`:''}${shots.length?`<p><b>${tr('shotlist')}:</b> ${shots.map(esc).join(', ')}</p>`:''}${item.notes?`<p>${esc(item.notes)}</p>`:''}</article>`}).join('');return `<section class="book-template-section"><h2>${tr('equipmentList')}</h2>${rows||`<p>${tr('equipmentEmpty')}</p>`}</section>`}
function productionBookReferenceImagesMarkup(){
  const entries=[],add=(image,context)=>{if(image?.src)entries.push({image,context})};
  for(const [index,scene] of (project.scenes||[]).entries()){
    const context=`${tr('scene')} ${index+1} · ${scene.heading||''}`;
    for(const image of scene.images||[])add(image,context);
    for(const kind of ['light','sound'])for(const image of scene.productionReferences?.[kind]||[])add(image,`${context} · ${tr(kind)}`)
  }
  for(const [index,shot] of (project.shots||[]).entries()){
    const context=`${tr('shot')} ${index+1} · ${project.scenes[shot.scene]?.heading||tr('sceneUnassigned')}`;
    add(shot.image,context);
    for(const kind of ['light','sound'])for(const image of shot.productionReferences?.[kind]||[])add(image,`${context} · ${tr(kind)}`)
  }
  for(const [kind,label] of [['characters','characters'],['locations','locations']])for(const entity of project[kind]||[])add(entity.image,`${tr(label)} · ${entity.name||''}`);
  for(const kind of ['light','sound'])for(const image of project.productionReferences?.[kind]||[])add(image,`${tr(kind)} · ${tr('project')}`);
  return `<section class="book-template-section book-reference-images"><h2>${tr('referenceImages')}</h2>${entries.map(({image,context})=>`<figure class="book-scene-image"><b>${esc(context)}</b>${lightingPlotPrintMarkup(image)}<figcaption>${esc(image.caption||'')} · ${esc(image.source||'')} · ${esc(image.creator||'')} · ${esc(image.date||'')} · ${esc(image.rights||'')} · ${esc(image.notes||'')}</figcaption></figure>`).join('')||`<p>${tr('reportEmpty')}</p>`}</section>`
}
