  const days=(project.shootDays||[]).map((day,dayIndex)=>{const sceneIds=Array.isArray(day.scenes)?day.scenes:project.scenes.map((_,index)=>index),scenes=sceneIds.map(index=>project.scenes[index]).filter(Boolean),people=(project.people||[]).filter(person=>person.day==='all'||Number(person.day)===dayIndex),shots=(project.shots||[]).filter(shot=>Number(shot.day||0)===dayIndex);const blocks={productionDetails:details(day),schedule:schedule(day),castCrew:castCrew(people,dayIndex,day),safety:safety(day),scenes:sceneList(scenes,sceneIds),shotlist:shotList(shots)};const body=template.sections.filter(key=>dailyKeys.has(key)).map(key=>blocks[key]).join('');return body?`<section class="book-day" data-book-day="${dayIndex}"><h2>${tr('shootDay')} ${dayIndex+1}${day.date?` · ${esc(day.date)}`:''} <small>${esc(day.status||tr('status'))}</small></h2><div class="book-template-day">${body}</div></section>`:''}).join('');
