async function createMoodboard(){const name=await askText(tr('newMoodboard'),tr('defaultMoodboard'));if(!name?.trim())return;const board={id:id(),name:name.trim()};project.moodboards.push(board);activeMoodboardId=board.id;render();scheduleSave()}
function deleteMoodboard(){if(project.moodboards.length<=1)return;const board=project.moodboards.find(item=>item.id===activeMoodboardId);if(!confirm(`${tr('deleteMoodboardConfirm')} (${board?.name||''})`))return;project.moodboard=project.moodboard.filter(item=>item.boardId!==activeMoodboardId);project.moodboards=project.moodboards.filter(item=>item.id!==activeMoodboardId);activeMoodboardId=project.moodboards[0].id;render();scheduleSave()}
function groupMoodItems(){const indices=[...selectedMoodItems].filter(index=>project.moodboard[index]?.boardId===activeMoodboardId);if(indices.length<2)return;const groupId=id();for(const index of indices)project.moodboard[index].groupId=groupId;render();scheduleSave()}
function ungroupMoodItems(){const indices=[...selectedMoodItems].filter(index=>project.moodboard[index]?.boardId===activeMoodboardId);for(const index of indices)delete project.moodboard[index].groupId;render();scheduleSave()}
function applyMoodStyle(index){const item=project.moodboard[index],element=document.querySelector(`[data-mood-item="${index}"]`);if(!item||!element)return;element.style.left=`${item.x}%`;element.style.top=`${item.y}%`;element.style.width=`${item.w}%`;element.style.height=`${item.h}%`}
function bindMoodboardInteractions(){const board=$('.board');if(!board||!project)return;document.querySelectorAll('[data-mood-select]').forEach(button=>button.onclick=event=>{const index=Number(button.dataset.moodSelect);if(event.shiftKey){if(selectedMoodItems.has(index))selectedMoodItems.delete(index);else selectedMoodItems.add(index)}else if(selectedMoodItems.size===1&&selectedMoodItems.has(index))selectedMoodItems.clear();else{selectedMoodItems.clear();selectedMoodItems.add(index)}render()});
  board.querySelectorAll('[data-mood-drag]').forEach(handle=>{handle.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();const index=Number(handle.dataset.moodDrag),item=project.moodboard[index];if(!item)return;if(!selectedMoodItems.has(index)){selectedMoodItems.clear();selectedMoodItems.add(index);board.querySelectorAll('.board-item').forEach(card=>card.classList.toggle('is-selected',Number(card.dataset.moodItem)===index))}const indices=[...selectedMoodItems];if(item.groupId)project.moodboard.forEach((other,otherIndex)=>{if(other.groupId===item.groupId&&!indices.includes(otherIndex))indices.push(otherIndex)});const initial=new Map(indices.map(i=>[i,{x:Number(project.moodboard[i].x),y:Number(project.moodboard[i].y)}])),rect=board.getBoundingClientRect(),startX=event.clientX,startY=event.clientY;handle.setPointerCapture(event.pointerId);const move=e=>{const dx=(e.clientX-startX)/rect.width*100,dy=(e.clientY-startY)/rect.height*100;for(const i of indices){const target=project.moodboard[i],origin=initial.get(i);target.x=Math.max(0,Math.min(100-target.w,origin.x+dx));target.y=Math.max(0,Math.min(100-target.h,origin.y+dy));applyMoodStyle(i)}};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);scheduleSave()};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end,{once:true});handle.addEventListener('pointercancel',end,{once:true})};handle.onkeydown=event=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const index=Number(handle.dataset.moodDrag),item=project.moodboard[index],step=event.shiftKey?5:1;if(event.key==='ArrowLeft')item.x=Math.max(0,item.x-step);if(event.key==='ArrowRight')item.x=Math.min(100-item.w,item.x+step);if(event.key==='ArrowUp')item.y=Math.max(0,item.y-step);if(event.key==='ArrowDown')item.y=Math.min(100-item.h,item.y+step);applyMoodStyle(index);scheduleSave()}});
  board.querySelectorAll('[data-mood-resize]').forEach(handle=>{handle.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();event.stopPropagation();const index=Number(handle.dataset.moodResize),item=project.moodboard[index],rect=board.getBoundingClientRect(),startX=event.clientX,startY=event.clientY,startW=Number(item.w),startH=Number(item.h);handle.setPointerCapture(event.pointerId);const move=e=>{item.w=Math.max(16,Math.min(60,startW+(e.clientX-startX)/rect.width*100));item.h=Math.max(20,Math.min(60,startH+(e.clientY-startY)/rect.height*100));item.x=Math.min(item.x,100-item.w);item.y=Math.min(item.y,100-item.h);applyMoodStyle(index)};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);scheduleSave()};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end,{once:true});handle.addEventListener('pointercancel',end,{once:true})};handle.onkeydown=event=>{const index=Number(handle.dataset.moodResize),item=project.moodboard[index],step=event.shiftKey?5:1;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();if(event.key==='ArrowLeft')item.w=Math.max(16,item.w-step);if(event.key==='ArrowRight')item.w=Math.min(60,item.w+step);if(event.key==='ArrowUp')item.h=Math.max(20,item.h-step);if(event.key==='ArrowDown')item.h=Math.min(60,item.h+step);item.x=Math.min(item.x,100-item.w);item.y=Math.min(item.y,100-item.h);applyMoodStyle(index);scheduleSave()}}})}
async function saveCollaborationAdminSettingsForm(event){event.preventDefault();const data=new FormData(event.target);try{collaborationAdminSettings=await window.studio.saveCollaborationAdminSettings({endpoint:data.get('endpoint'),token:data.get('token'),clearToken:data.has('clearToken')});adminInvites=[];adminInvitesProjectId='';adminInvitesLoaded=false;render();toast(tr('collabAdminSettingsSaved'))}catch(error){toast(`${tr('collaborationFailed')}: ${error.message}`)}}
