async function createCollaborationAdminInvite(event){event.preventDefault();const data=new FormData(event.target),targetProjectId=String(data.get('projectId')||'');try{const result=await window.studio.collaborationAdminRequest({operation:'create',projectId:targetProjectId,role:data.get('role'),name:data.get('name')});adminInviteToken=result.token;adminInviteTokenProjectId=targetProjectId;adminInvitesProjectId=targetProjectId;adminInvitesLoaded=false;adminInvites=[];render();try{const listed=await window.studio.collaborationAdminRequest({operation:'list',projectId:targetProjectId});if(project?.id===targetProjectId){adminInvites=listed;adminInvitesLoaded=true;render()}}catch(error){toast(`${tr('collabAdminRequestFailed')}: ${error.message}`)}}catch(error){toast(`${tr('collabAdminRequestFailed')}: ${error.message}`)}}
