async function connectCollaboration(){if(!project)return;collaborationAccess={content:null,comments:null};const title=project.title;try{const credentials=await window.studio.getCollaborationCredentials();if(!confirm(tr('collaborationConfirm').replace('{title}',title).replace('{url}',credentials.endpoint)))return;clearTimeout(timer);for(const scene of project.scenes||[])scene.editHistoryId||=id();if(!(await persist()))return;await window.studio.createRecoveryBackup(project.id);collaborationState='connecting';render();const session=await window.ScriptStudioCollaboration.connectProject({url:credentials.endpoint,projectId:project.id,token:credentials.token,username:credentials.username,initialProject:cloneData(project),onProject:remote=>{if(!remote||remote.id!==project?.id)return;historyApplying=true;project=remote;const remoteHistory=historyState(remote);if(remoteHistory.undo.length||remoteHistory.redo.length)toast(tr('collabUndoHistoryReset'));remoteHistory.snapshot=contentSnapshot(remote);remoteHistory.undo=[];remoteHistory.redo=[];projects=[remote,...projects.filter(item=>item.id!==remote.id)];window.studio.saveProject(remote).then(saved=>{project.updatedAt=saved;historyApplying=false}).catch(error=>{historyApplying=false;toast(`${tr('collaborationFailed')}: ${error.message}`)});render()},onStatus:status=>{collaborationState=status==='connected'?'connected':status==='connecting'?'connecting':status;render()},onAccess:(kind,scope)=>{collaborationAccess[kind]=scope;applyCollaborationPermissions()},onPresence:users=>{collaborators=users;updateScenePresence();},onError:error=>{collaborationState='error';toast(`${tr('collaborationFailed')}: ${error.message}`)}});liveCollaboration=session;collaborationState='connected';render()}catch(error){collaborationState='error';render();toast(`${tr('collaborationFailed')}: ${error.message}`)}}
