function bindProductionPresets(){
  const editable=()=>collaborationAccess.content!=='readonly';
  const lightOwner=button=>button.dataset.ownerKind==='scene'?project.scenes?.[Number(button.dataset.ownerIndex)]:project.shots?.[Number(button.dataset.ownerIndex)];
  const lightLocked=(button,owner)=>button.dataset.ownerKind==='scene'?!!owner?.locked:!!project.shootDays?.[Number(owner?.day??0)]?.locked;
  document.querySelectorAll('[data-save-preset]').forEach(button=>button.onclick=()=>{
    if(!editable())return;const kind=button.dataset.savePreset,index=Number(button.dataset.index);let source;
    if(kind==='shot'){if(project.shootDays?.[activeDayIndex]?.locked)return;source=project.shots?.[index]}
    else if(kind==='equipment')source=project.equipment?.[index];
    else if(kind==='lighting'){const owner=lightOwner(button);if(!owner||lightLocked(button,owner))return;source=owner.lightingSetup?.[index]}
    if(source)saveProductionPreset(kind,source);
  });
  document.querySelectorAll('[data-apply-preset]').forEach(button=>button.onclick=()=>{
    if(!editable())return;const kind=button.dataset.applyPreset,id=button.closest('.preset-toolbar')?.querySelector('[data-preset-select]')?.value,preset=(project.productionPresets||[]).find(item=>item.id===id&&item.kind===kind),values=window.TakeveraProductionTools.presetValues(kind,preset?.values);if(!values)return;
    if(kind==='shot'){if(project.shootDays?.[activeDayIndex]?.locked)return;project.shots||=[];project.shots.push({day:activeDayIndex,scene:'',description:'',framing:'',movement:'',lens:'',sound:'',light:'',duration:'',notes:'',...values})}
    else if(kind==='equipment'){project.equipment||=[];project.equipment.push({name:'',category:'',quantity:1,owner:'',notes:'',...values,status:'needed',scenes:[],shots:[]});equipmentFilterStatus='all'}
    else if(kind==='lighting'){const owner=lightOwner(button);if(!owner||lightLocked(button,owner))return;owner.lightingSetup||=[];owner.lightingSetup.push({source:'',position:'',modifier:'',power:'',safety:'',...values})}
    else return;scheduleSave();render();
  });
  document.querySelectorAll('[data-delete-preset]').forEach(button=>button.onclick=()=>{
    if(!editable())return;const id=button.closest('.preset-toolbar')?.querySelector('[data-preset-select]')?.value,index=(project.productionPresets||[]).findIndex(item=>item.id===id&&item.kind===button.dataset.deletePreset);if(index<0||!confirm(tr('deletePresetConfirm').replace('{name}',project.productionPresets[index].name)))return;project.productionPresets.splice(index,1);scheduleSave();render();
  });
}
