function shortcuts(e){if(e.key==='Escape'&&projectSearchOpen){projectSearchOpen=false;render();return}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){if(e.target.matches('input,textarea,[contenteditable=true]'))return;e.preventDefault();applyHistory(e.shiftKey?'redo':'undo')}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='n'){e.preventDefault();addProject()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();persist()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='f'){e.preventDefault();if(project){projectSearchOpen=true;render();$('#project-search-input')?.focus()}else $('#search-projects')?.focus()}if((e.metaKey||e.ctrlKey)&&e.shiftKey&&e.key.toLowerCase()==='n'&&project&&section==='script'){e.preventDefault();project.scenes.push({heading:productionKind()==='theatre'?`${tr('stageSceneHeading')}`:'INT. LOCATIE - DAG',action:'',character:'',dialogue:'',location:'',duration:0,notes:'',elements:[],comments:[]});sceneIndex=project.scenes.length-1;render();scheduleSave()}document.addEventListener('keydown',shortcuts,{once:true})}
